corrected_code:
package warehouse

import (
	"context"
	"errors"
	"myapp/inventory"
)

type RestockJob struct {
	ProductID   string
	Quantity    int
	InitiatedBy string
}

type RestockWorker struct {
	InvStore inventory.Store
}

func (w *RestockWorker) ApplyRestock(ctx context.Context, job RestockJob) error {
	ownerVendorID, err := w.InvStore.GetVendorIDForProduct(ctx, job.ProductID)
	if err != nil || ownerVendorID != job.InitiatedBy {
		return errors.New("worker rejected: initiating vendor does not own product")
	}

	return w.InvStore.AddStock(ctx, job.ProductID, job.Quantity)
}
